 void diagnostics(){
  Agenda.channel(this);NotificationManager nm=getSystemService(NotificationManager.class);AlarmManager alarm=getSystemService(AlarmManager.class);PowerManager power=getSystemService(PowerManager.class);ActivityManager activity=getSystemService(ActivityManager.class);
  boolean canNotify=Build.VERSION.SDK_INT<33||checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)==android.content.pm.PackageManager.PERMISSION_GRANTED;
  boolean enabled=nm.areNotificationsEnabled();NotificationChannel channel=nm.getNotificationChannel(Agenda.CHANNEL);
  String importance=channel==null?"未创建":channel.getImportance()==NotificationManager.IMPORTANCE_HIGH?"高":channel.getImportance()==NotificationManager.IMPORTANCE_DEFAULT?"默认":channel.getImportance()==NotificationManager.IMPORTANCE_LOW?"低":channel.getImportance()==NotificationManager.IMPORTANCE_MIN?"最低":"已关闭";
  boolean exact=Build.VERSION.SDK_INT<31||alarm.canScheduleExactAlarms();int filter=nm.getCurrentInterruptionFilter();
  String dnd=filter==NotificationManager.INTERRUPTION_FILTER_ALL?"关闭":filter==NotificationManager.INTERRUPTION_FILTER_PRIORITY?"仅优先":filter==NotificationManager.INTERRUPTION_FILTER_ALARMS?"仅闹钟":"完全静音";
  boolean battery=power.isIgnoringBatteryOptimizations(getPackageName());boolean restricted=activity.isBackgroundRestricted();
  LinearLayout form=Ui.column(this);form.setPadding(Ui.dp(this,20),Ui.dp(this,4),Ui.dp(this,20),Ui.dp(this,12));
  form.addView(Ui.text(this,"通知与定时诊断",20));form.addView(Ui.hint(this,"状态读取自本机系统。应用不会自动修改权限或通道设置。"));
  form.addView(Ui.hint(this,"通知权限："+(canNotify?"已允许":"未允许")));form.addView(Ui.hint(this,"系统通知总开关："+(enabled?"开启":"关闭")));
  form.addView(Ui.hint(this,"课程通知通道："+Agenda.CHANNEL+" · 重要度 "+importance));
  form.addView(Ui.hint(this,"横幅：系统没有提供读取开关；若重要度为“高”仍无横幅，请在“课程通知通道设置”中核对横幅/悬浮通知。"));
  form.addView(Ui.hint(this,"精确定时："+(exact?"已允许":"未允许（提醒可能延迟，宽限内会补发）")));
  form.addView(Ui.hint(this,"勿扰模式："+dnd+(filter==NotificationManager.INTERRUPTION_FILTER_ALL?"":" · 可能隐藏横幅")));
  form.addView(Ui.hint(this,"电池优化："+(battery?"未限制":"已限制 · 可能延迟")));form.addView(Ui.hint(this,"后台限制："+(restricted?"已限制":"未限制")));
  form.addView(Ui.hint(this,"下一次提醒："+formatTime(Agenda.nextAt(this))+"\n已排程 "+Agenda.scheduledCount(this)+" 个 · "+scheduleModeLabel(Agenda.lastScheduleMode(this))));
  form.addView(Ui.hint(this,"最近排程："+formatTime(Agenda.lastScheduleAt(this))+(Agenda.alarmError(this).isEmpty()?"":"\n"+Agenda.alarmError(this))));
  form.addView(Ui.hint(this,"最近发送："+Agenda.lastResult(this)));
  if(!canNotify)Ui.button(this,form,"允许通知",this::permissions);
  Ui.link(this,form,"系统通知设置  ›",()->startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName())));
  Ui.link(this,form,"课程通知通道设置  ›",this::openChannelSettings);
  Ui.link(this,form,"精确定时设置  ›",()->{try{startActivity(new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName())));}catch(Exception error){Ui.error(this,error);}});
  Ui.link(this,form,"电池优化设置  ›",()->startActivity(new Intent(Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS)));
  Ui.link(this,form,"勿扰模式设置  ›",()->{try{startActivity(new Intent("android.settings.ZEN_MODE_SETTINGS"));}catch(Exception error){Ui.error(this,error);}});
  Ui.button(this,form,"立即发送上课提醒测试",()->runTest("class"));Ui.button(this,form,"立即发送扫码提醒测试",()->runTest("scan"));Ui.button(this,form,"1 分钟后发送定时测试",this::testScheduled);
  form.addView(Ui.hint(this,"测试与正式提醒使用同一通道、同样静音。定时测试结果可在“最近发送”查看。"));
  ScrollView scroll=new ScrollView(this);scroll.addView(form);new AlertDialog.Builder(this).setTitle("通知诊断与测试").setView(scroll).setPositiveButton("关闭",null).show();
 }
 void runTest(String kind){boolean ok=Agenda.testNotification(this,kind);new AlertDialog.Builder(this).setTitle(ok?"测试通知已提交":"测试通知未提交").setMessage(Agenda.lastResult(this)+"\n\n应用无法读取系统是否实际展示横幅；请到“课程通知通道设置”确认横幅/悬浮通知。").setPositiveButton("通道设置",(d,n)->openChannelSettings()).setNegativeButton("关闭",null).show();}
 void testScheduled(){try{PendingIntent p=PendingIntent.getBroadcast(this,Agenda.TEST_ALARM,new Intent(this,AgendaReceiver.class).setAction(Agenda.TEST_ACTION).putExtra("kind","class"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);AlarmManager am=getSystemService(AlarmManager.class);long at=System.currentTimeMillis()+60000;if(Build.VERSION.SDK_INT<31||am.canScheduleExactAlarms())am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,p);else am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,p);Toast.makeText(this,"已安排 1 分钟后的课程通道测试；结果可在诊断的“最近发送”查看",Toast.LENGTH_LONG).show();}catch(Exception error){Ui.error(this,error);}}
 static String formatTime(long t){return t<=0?"未安排":Instant.ofEpochMilli(t).atZone(ZoneId.systemDefault()).format(DateTimeFormatter.ofPattern("MM-dd HH:mm"));}
 static String scheduleModeLabel(String mode){return "exact".equals(mode)?"精确定时":"inexact".equals(mode)?"非精确（系统可能延迟）":"";}
 void defaults(){LinearLayout form=Ui.column(this);form.setPadding(Ui.dp(this,20),0,Ui.dp(this,20),0);EditText lead=Ui.field(this,form,"新课程上课前几分钟提醒",String.valueOf(Agenda.prefs(this).getInt("defaultLead",10)),InputType.TYPE_CLASS_NUMBER);EditText scan=Ui.field(this,form,"新课程扫码前几分钟提醒",String.valueOf(Agenda.prefs(this).getInt("defaultScanLead",3)),InputType.TYPE_CLASS_NUMBER);form.addView(Ui.text(this,"已有课程可单独修改；默认值只影响新课程。",13));AlertDialog d=new AlertDialog.Builder(this).setTitle("默认提醒时间").setView(form).setPositiveButton("保存",null).setNegativeButton("取消",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{try{int l=minutes(lead),s=minutes(scan);Agenda.prefs(this).edit().putInt("defaultLead",l).putInt("defaultScanLead",s).apply();d.dismiss();}catch(Exception e){Ui.error(this,e);}}));d.show();}
